@resultBuilder struct Menu {
  static func buildBlock(_ s: String...)
    -> [String] { s } }
@Menu var items: [String] { "Home"; "Help" }
print(items)

@resultBuilder struct Words {
  static func buildBlock(_ w: String...)
    -> String { w.joined(separator: " ") } }
@Words func hi() -> String {
    "Hello"; "Mina" }
print(hi())

@resultBuilder struct Sum {
  static func buildBlock(_ n: Int...)
    -> Int { n.reduce(0, +) } }
@Sum var total: Int { 1; 2; 3 }
print(total)

